import os, json, numpy as np

N = 26
SAFETY = 1e-9
P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
BASE = 'storage/noesis/exports/sota_243'
TOLS = [1e-9, 5e-9, 1e-8, 2e-8]
OUT = os.path.join(BASE, 'active_counts_vs_tol.json')

def load(cpath, rpath):
    c = np.loadtxt(cpath, dtype=float).reshape(N,2)
    r = np.loadtxt(rpath, dtype=float).reshape(N,)
    return c, r

def load_summary(tol):
    tag = f'1e{abs(int(round(np.log10(tol))))}'
    p = os.path.join(BASE, f'summary_tol{tag}.json')
    if os.path.exists(p):
        try:
            with open(p, 'r') as f:
                return json.load(f)
        except Exception:
            return None
    return None

def construct_packing():
    c, r = load(P_C, P_R)
    table = []
    for t in TOLS:
        s = load_summary(t) or {}
        table.append({
            'tol': t,
            'sum_radii': s.get('sum_radii', float(np.sum(r))),
            'active_boundary_count': s.get('active_boundary_count', s.get('boundary_count')),
            'active_pair_count': s.get('active_pair_count', s.get('pair_count')),
            'degree_histogram': s.get('degree_histogram', {})
        })
    os.makedirs(BASE, exist_ok=True)
    try:
        with open(OUT, 'w') as f:
            json.dump({'counts': table}, f, indent=2)
    except Exception:
        pass
    return c.astype(float), np.maximum(r - SAFETY, 1e-6).astype(float)
